import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{neuralFigure,neuralSVG,nt}from './neural-figures.js?v=20261023-physicscomplete01';import{buildNeural}from './neural-meshes.js?v=20261023-physicscomplete01';
export function showNeural(spec='neuron:normal',w={}){let[key,state]=spec.split(':'),kind=({'homeostasis':'control','nervous-system':'neuron','reflex-arc':'reflex','synapses':'synapse','reaction-time':'ruler'})[key]||key,o={kind,state:state||'normal',...w},name=w.title||({control:'Regulate internal conditions',neuron:'Inspect a neurone',reflex:'Trace a spinal reflex',synapse:'Across a chemical synapse',ruler:'Prepare the reaction-time investigation',data:'Collect the original evidence',graph:'Plot the original means'})[kind]||'Trace the signal',figure=o.concealed?neuralSVG(nt(280,190,'Predict, then reveal the comparison',22),name):neuralFigure({...o,title:name});if(['data','graph'].includes(kind)){renderDiagram(name,w.stateLabel||'Original simulated evidence',figure,'NERVOUS SYSTEM EVIDENCE');return;}renderCustomModel({name,formula:w.stateLabel||'Symbolic signal pathway; inspect the labels',kicker:'SCHEMATIC NERVOUS SYSTEM MODEL',aria:name+'. Symbolic geometry; labelled diagram available.',atoms:[],bonds:[],radius:2.65,viewKey:'neural-'+kind,startPaused:true,note:'Enlarged structures and gaps · symbolic speed and stage time',diagram:figure,build:(g,T)=>buildNeural(g,T,o)});}
